CREATE POLICY "library covers own read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'library-covers' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "library covers own insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'library-covers' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "library covers own delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'library-covers' AND (storage.foldername(name))[1] = auth.uid()::text);